function toggleTodosRoles(checkbox){const checkboxes=document.querySelectorAll('[data-js-rol][type="checkbox"]');checkboxes.forEach(cb=>cb.checked=checkbox.checked)}function confirmarCambios(event){const checkboxes=document.querySelectorAll('[data-js-rol][type="checkbox"]:checked'),cantidad=checkboxes.length;return confirm(`¿Estás seguro de asignar ${cantidad} rol(es) a este usuario?

Esta acción quedará registrada en la auditoría.`)?!0:(event.preventDefault(),!1)}